create table fin_accounts(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,provider text not null check(provider in ('asaas','stripe')),environment text not null,fingerprint text not null,unique(tenant_id,provider,environment,fingerprint));
create table fin_customers(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,external_id text not null,name text not null,document text,phone text,email text,birthday date,customer_since date,contact_id int references contacts,communication_allowed boolean not null default false,updated_at timestamptz not null default now(),unique(account_id,external_id));
create table fin_invoices(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,external_id text not null,customer_external_id text,subscription_external_id text,description text,status text not null,provider_status text not null,amount numeric not null,paid_amount numeric not null default 0,balance numeric not null,currency text not null default 'BRL',due_date date,paid_date date,created_date date,invoice_url text,updated_at timestamptz not null default now(),unique(account_id,external_id));
create index fin_due on fin_invoices(account_id,due_date,status);
create table fin_services(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,external_id text not null,customer_external_id text,name text,status text,amount numeric,currency text,cycle text,next_due_date date,unique(account_id,external_id));
create table fin_products(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,name text not null,kind text not null check(kind in ('product','service')),amount numeric not null check(amount>0),currency text not null,recurring boolean not null default false,cycle text not null default 'MONTHLY',billing_type text not null default 'UNDEFINED',active boolean not null default true,created_at timestamptz not null default now());
create table fin_sync(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,phase text not null default 'customers',kind text not null default 'full' check(kind in ('full','daily')),cursor text not null default '',status text not null default 'pending' check(status in ('pending','running','completed','failed')),rows_seen int not null default 0,from_date date not null,started_at timestamptz not null default now(),finished_at timestamptz,error text);
create unique index fin_one_sync on fin_sync(account_id) where status in ('pending','running');
create table fin_operations(id uuid primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,request_key text not null,status text not null default 'check_required',input jsonb not null,result jsonb,steps jsonb not null default '{}',created_at timestamptz not null default now(),unique(account_id,request_key));
create table fin_notifications(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,customer_id int references fin_customers,invoice_id int references fin_invoices,kind text not null,occurrence text not null,channel_id int references channels,contact_id int references contacts,conversation_id int references conversations,bot_id int references bots,body text,template jsonb,status text not null default 'pending' check(status in ('pending','sending','sent','blocked','cancelled','check_required')),detail text,message_id bigint references messages,created_at timestamptz not null default now(),claimed_at timestamptz,sent_at timestamptz,unique(account_id,kind,occurrence));
do $$ declare r record;begin for r in select * from (values('fin_accounts',''),('fin_customers','fin_accounts,account_id,contacts,contact_id'),('fin_invoices','fin_accounts,account_id'),('fin_services','fin_accounts,account_id'),('fin_products','fin_accounts,account_id'),('fin_sync','fin_accounts,account_id'),('fin_operations','fin_accounts,account_id'),('fin_notifications','fin_accounts,account_id,fin_customers,customer_id,fin_invoices,invoice_id,channels,channel_id,contacts,contact_id,conversations,conversation_id,bots,bot_id,messages,message_id')) v(t,a) loop
 execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format($f$create policy tenant_iso on %I using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int)$f$,r.t);if r.a<>'' then execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.a,',')) x));end if;end loop;end $$;
alter table fin_products add column remote_price_id text;
alter table fin_products add column remote_product_id text;
create unique index fin_remote_price on fin_products(account_id,remote_price_id) where remote_price_id is not null;
create table fin_audit(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references fin_accounts,actor_id int references users,type text not null,data jsonb not null default '{}',at timestamptz not null default now());
alter table fin_audit enable row level security;alter table fin_audit force row level security;create policy tenant_iso on fin_audit using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int);
create trigger fk_guard before insert or update on fin_audit for each row execute function fk_guard('fin_accounts','account_id','users','actor_id');
create index fin_customer_invoices on fin_invoices(account_id,customer_external_id);
